import java.util.*;

class Solution {
    public int calculate(String s) {
        Deque<Integer> terms = new ArrayDeque<>();
        int number = 0;
        char operator = '+';

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                number = number * 10 + (c - '0');
            }

            if ((!Character.isDigit(c) && c != ' ') || i == s.length() - 1) {
                apply(terms, operator, number);
                operator = c;
                number = 0;
            }
        }

        int result = 0;
        for (int term : terms) {
            result += term;
        }
        return result;
    }

    private void apply(Deque<Integer> terms, char operator, int number) {
        if (operator == '+') {
            terms.push(number);
        } else if (operator == '-') {
            terms.push(-number);
        } else if (operator == '*') {
            terms.push(terms.pop() * number);
        } else if (operator == '/') {
            terms.push(terms.pop() / number);
        }
    }
}

